mapper.select:
select ss.id, ss.sku_id as skuId, ss.size, ss.stock, sk.color_name as colorName, sp.name as spuName, sp.brand from shoe_sku_size ss inner join shoe_sku sk on ss.sku_id = sk.id inner join shoe_spu sp on sk.spu_id = sp.id
and sp.name like concat('%', #{spuName}, '%')
and sp.brand = #{brand}
and ss.size = #{size}
order by sp.id desc, sk.id desc, ss.size asc
